-- Final check after every migration (read only). Expect ONE row and every value true.
select
  (select count(*) = 12 from information_schema.tables where table_schema = 'public' and table_name in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log', 'ii_risk_free_refresh_attempts', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_result_cache', 'nav2_report_render_tokens', 'nav2_correction_events')) as twelve_tables,
  (select count(*) = 16 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = any (array['is_risk_free_data_admin', 'is_risk_free_series_switch_admin', 'commit_risk_free_upload', 'record_risk_free_refresh_results', 'resolve_risk_free_review_item', 'correct_risk_free_observation', 'set_risk_free_series_state', 'ii_risk_free_append_only', 'ii_risk_free_obs_guard', 'nav2_reports_immutable', 'nav2_capture_reference_correction', 'nav2_capture_risk_free_correction', 'nav2_monitor_cell', 'nav2_monitoring_snapshot', 'nav2_refresh_attempt_summary', 'nav2_viewer_has_premium'])) as sixteen_functions,
  (select count(*) = 8 from pg_policies where schemaname = 'public' and tablename in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies')) as eight_policies,
  (select count(*) = 4 from public.ii_reference_job_control where job_key in ('nav2_risk_free_weekly_refresh', 'nav2_fund_analytics', 'nav2_trigger_planner', 'nav2_correction_worker') and enabled = false) as four_switches_all_off,
  (select count(*) = 0 from public.admin_users where can_upload_risk_free_data or can_switch_risk_free_series) as nobody_holds_the_new_permissions_yet,
  (select count(*) = 2 from public.ii_risk_free_series where enabled) as two_series_enabled,
  (select count(*) = 0 from public.ii_risk_free_observations) as no_rates_loaded_yet,
  (select count(*) = 0 from public.nav2_fund_analytics_reports) as no_reports_yet;
